  <style>
    :root {
      color-scheme: dark;
      --bg: #0d1117;
      --panel: #161b22;
      --panel-elevated: #1f2630;
      --border: #30363d;
      --text: #f0f6fc;
      --muted: #8b949e;
      --accent: #58a6ff;
      --accent-strong: #1f6feb;
      --success: #3fb950;
      --shadow: rgba(1, 4, 9, 0.55);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, rgba(88, 166, 255, 0.2), transparent 32rem),
        radial-gradient(circle at bottom right, rgba(63, 185, 80, 0.12), transparent 28rem),
        var(--bg);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 48px 20px;
    }

