      border: 1px solid var(--border);
      border-radius: 28px;
      box-shadow: 0 28px 80px var(--shadow);
      overflow: hidden;
    }

    .quiz-header {
      padding: 36px 40px 28px;
      border-bottom: 1px solid var(--border);
    }

