      color: var(--accent);
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      margin: 0 0 12px;
      text-transform: uppercase;
    }

    h1 {
      font-size: clamp(2rem, 6vw, 3.5rem);
      line-height: 1;
      margin: 0 0 14px;
    }

    .intro {
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.6;
      margin: 0;
      max-width: 720px;
    }

    form {
      display: grid;
      gap: 24px;
      padding: 32px 40px 40px;
    }

    .form-field {
      background: rgba(13, 17, 23, 0.56);
      border: 1px solid var(--border);
      border-radius: 22px;
      padding: 24px;
    }

    .question-title {
      align-items: flex-start;
      display: flex;
      gap: 14px;
      margin: 0 0 8px;
    }

    .question-number {
      background: rgba(88, 166, 255, 0.14);
      border: 1px solid rgba(88, 166, 255, 0.38);
      border-radius: 999px;
      color: #c9e4ff;
      flex: 0 0 auto;
      font-size: 0.88rem;
      font-weight: 700;
      padding: 5px 11px;
    }

    .question-text {
      font-size: 1.18rem;
      font-weight: 750;
      line-height: 1.4;
    }

    .help-text {
      color: var(--muted);
      font-size: 0.95rem;
      line-height: 1.5;
      margin: 0 0 18px 52px;
    }

    .choices {
      display: grid;
      gap: 12px;
      margin-top: 18px;
    }

    .choice {
      align-items: center;
      background: rgba(31, 38, 48, 0.7);
      border: 1px solid transparent;
      border-radius: 16px;
      cursor: pointer;
      display: flex;
      gap: 13px;
      padding: 14px 16px;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      background: rgba(56, 68, 84, 0.62);
      border-color: rgba(88, 166, 255, 0.28);
