    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, rgba(88, 166, 255, 0.2), transparent 32rem),
        radial-gradient(circle at bottom right, rgba(63, 185, 80, 0.12), transparent 28rem),
        var(--bg);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 48px 20px;
    }

    .quiz-app {
      width: min(920px, 100%);
    }

    .quiz-card {
      background: linear-gradient(180deg, rgba(31, 38, 48, 0.96), rgba(22, 27, 34, 0.96));
      border: 1px solid var(--border);
      border-radius: 28px;
      box-shadow: 0 28px 80px var(--shadow);
      overflow: hidden;
    }

    .quiz-header {
      padding: 36px 40px 28px;
      border-bottom: 1px solid var(--border);
    }

    .eyebrow {
      color: var(--accent);
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      margin: 0 0 12px;
      text-transform: uppercase;
    }

    h1 {
      font-size: clamp(2rem, 6vw, 3.5rem);
      line-height: 1;
      margin: 0 0 14px;
    }

    .intro {
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.6;
      margin: 0;
      max-width: 720px;
    }

    form {
      display: grid;
      gap: 24px;
      padding: 32px 40px 40px;
    }

    .form-field {
      background: rgba(13, 17, 23, 0.56);
      border: 1px solid var(--border);
      border-radius: 22px;
      padding: 24px;
    }

    .question-title {
      align-items: flex-start;
      display: flex;
      gap: 14px;
      margin: 0 0 8px;
    }

    .question-number {
      background: rgba(88, 166, 255, 0.14);
      border: 1px solid rgba(88, 166, 255, 0.38);
      border-radius: 999px;
      color: #c9e4ff;
      flex: 0 0 auto;
      font-size: 0.88rem;
      font-weight: 700;
      padding: 5px 11px;
    }

    .question-text {
      font-size: 1.18rem;
      font-weight: 750;
      line-height: 1.4;
    }

    .help-text {
      color: var(--muted);
      font-size: 0.95rem;
      line-height: 1.5;
      margin: 0 0 18px 52px;
    }

    .choices {
      display: grid;
      gap: 12px;
      margin-top: 18px;
    }

    .choice {
      align-items: center;
      background: rgba(31, 38, 48, 0.7);
      border: 1px solid transparent;
      border-radius: 16px;
      cursor: pointer;
      display: flex;
      gap: 13px;
      padding: 14px 16px;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      background: rgba(56, 68, 84, 0.62);
      border-color: rgba(88, 166, 255, 0.28);
      transform: translateY(-1px);
    }

    .choice input {
      accent-color: var(--accent);
      height: 18px;
      width: 18px;
    }

    .choice span {
      color: #dbe7f3;
      line-height: 1.35;
    }

    .actions {
      align-items: center;
      display: flex;
      gap: 16px;
      justify-content: space-between;
      margin-top: 4px;
    }

    button {
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      border: 0;
      border-radius: 999px;
      box-shadow: 0 12px 30px rgba(31, 111, 235, 0.36);
      color: white;
      cursor: pointer;
      font: inherit;
      font-weight: 800;
      padding: 14px 24px;
      transition: filter 160ms ease, transform 160ms ease;
    }

    button:hover {
      filter: brightness(1.08);
      transform: translateY(-1px);
    }

    .result {
      color: var(--success);
      font-weight: 700;
      min-height: 1.4em;
    }

    @media (max-width: 640px) {
      body {
        padding: 24px 12px;
      }

      .quiz-header,
      form {
        padding-left: 22px;
        padding-right: 22px;
      }

      .help-text {
        margin-left: 0;
      }

      .actions {
        align-items: stretch;
        flex-direction: column;
      }
    }
  </style>
</head>
<body>
  <main id="root" class="quiz-app"></main>

  <script>
    const questions = [
      {
        id: "language-types",
        prompt: "Which of these are programming languages?",
        helpText: "Select every option that is a language used to write software. More than one answer may be correct.",
        choices: ["Python", "HTML", "JavaScript", "Photoshop"]
      },
      {
        id: "compiled-languages",
        prompt: "Which languages are commonly compiled before execution?",
        choices: ["C", "Rust", "Go", "CSS"]
      },
      {
        id: "web-languages",
        prompt: "Which languages are commonly used to build web pages or web applications?",
        choices: ["JavaScript", "TypeScript", "Ruby", "SQL"]
      }
    ];

    function Choice({ questionId, label, index }) {
      const id = `${questionId}-${index}`;

      return `
        <label class="choice" for="${id}">
          <input type="checkbox" id="${id}" name="${questionId}" value="${label}">
          <span>${label}</span>
        </label>
      `;
    }

    function Question({ question, index }) {
      const helpText = question.helpText
        ? `<p class="help-text" id="${question.id}-help">${question.helpText}</p>`
        : "";
      const describedBy = question.helpText ? ` aria-describedby="${question.id}-help"` : "";

      return `
        <div class="form-field">
          <div class="question-title">
            <span class="question-number">${index + 1}</span>
            <span class="question-text">${question.prompt}</span>
          </div>
          ${helpText}
          <div class="choices" role="group" aria-label="${question.prompt}"${describedBy}>
            ${question.choices.map((choice, choiceIndex) => Choice({
              questionId: question.id,
              label: choice,
              index: choiceIndex
            })).join("")}
          </div>
        </div>
      `;
    }

    function QuizApp({ questions }) {
      return `
        <section class="quiz-card" aria-labelledby="quiz-title">
          <header class="quiz-header">
            <p class="eyebrow">Multiple select quiz</p>
            <h1 id="quiz-title">Computer Languages</h1>
            <p class="intro">Choose all answers that apply for each question, then submit your selections.</p>
          </header>
          <form id="quiz-form">
            ${questions.map((question, index) => Question({ question, index })).join("")}
            <div class="actions">
              <button type="submit">Submit answers</button>
              <output class="result" id="result" aria-live="polite"></output>
            </div>
          </form>
        </section>
      `;
    }

    document.querySelector("#root").innerHTML = QuizApp({ questions });

    document.querySelector("#quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();
      const selectedCount = document.querySelectorAll("input[type='checkbox']:checked").length;
      const result = selectedCount === 1 ? "1 answer selected." : `${selectedCount} answers selected.`;
      document.querySelector("#result").textContent = result;
    });
  </script>
</body>
</html>
